"""Filesystem metadata predicates for find-compatible command line tools."""
import fnmatch
import grp
import os
import pwd
import re
import stat
import time


def _cmp(value, spec):
    m = re.fullmatch(r'([+-]?)(\d+)', str(spec))
    if not m:
        return False
    op, n = m.group(1), int(m.group(2))
    return value > n if op == '+' else value < n if op == '-' else value == n


def _mode(spec, mode):
    """find -perm semantics: exact, all bits (-), or any bit (/)."""
    op = ''
    if spec.startswith(('-', '/', '+')):
        op, spec = spec[0], spec[1:]
    try:
        wanted = int(spec, 8)
    except ValueError:
        return False
    actual = stat.S_IMODE(mode)
    if op == '-':
        return actual & wanted == wanted
    if op == '/':
        return bool(actual & wanted)
    if op == '+':
        return (actual & wanted) == wanted
    return actual == wanted


def _size(spec, size):
    m = re.fullmatch(r'([+-]?)(\d+)([cwbkKMGTP]?)', str(spec))
    if not m:
        return False
    op, n, unit = m.groups()
    mult = {'': 512, 'b': 512, 'c': 1, 'w': 2, 'k': 1024, 'K': 1024,
            'M': 1024**2, 'G': 1024**3, 'T': 1024**4, 'P': 1024**5}[unit]
    # find rounds up to the selected unit before comparing.
    blocks = (size + mult - 1) // mult
    return _cmp(blocks, op + n)


def _type(st, wanted, follow=False):
    mode = st.st_mode
    if stat.S_ISLNK(mode) and follow:
        try:
            mode = os.stat(st._path).st_mode
        except (OSError, AttributeError):
            return False
    ty = ('b' if stat.S_ISBLK(mode) else 'c' if stat.S_ISCHR(mode) else
          'd' if stat.S_ISDIR(mode) else 'p' if stat.S_ISFIFO(mode) else
          'f' if stat.S_ISREG(mode) else 'l' if stat.S_ISLNK(mode) else
          's' if stat.S_ISSOCK(mode) else '?')
    return ty in wanted


def evaluate(name, arg, path, st, depth=0, follow=False, now=None):
    """Evaluate a stat-based predicate. Return None for unsupported predicates."""
    name = name.lstrip('-')
    if name == 'depth':
        return _cmp(depth, arg)
    if name == 'type':
        return _type(st, arg, follow)
    if name == 'xtype':
        return _type(st, arg, not follow)
    if name == 'size':
        return _size(arg, st.st_size)
    if name == 'perm':
        return _mode(arg, st.st_mode)
    if name in ('uid', 'gid', 'inum', 'links'):
        value = {'uid': st.st_uid, 'gid': st.st_gid, 'inum': st.st_ino,
                 'links': st.st_nlink}[name]
        return _cmp(value, arg)
    if name in ('user', 'group'):
        value = st.st_uid if name == 'user' else st.st_gid
        try:
            target = int(arg)
        except ValueError:
            try:
                target = pwd.getpwnam(arg).pw_uid if name == 'user' else grp.getgrnam(arg).gr_gid
            except KeyError:
                return False
        return value == target
    if name in ('nouser', 'nogroup'):
        try:
            pwd.getpwuid(st.st_uid) if name == 'nouser' else grp.getgrgid(st.st_gid)
            return False
        except KeyError:
            return True
    if name in ('name', 'iname'):
        pattern = arg.lower() if name == 'iname' else arg
        value = os.path.basename(path).lower() if name == 'iname' else os.path.basename(path)
        return fnmatch.fnmatchcase(value, pattern)
    if name in ('path', 'wholename', 'ipath', 'iwholename'):
        insensitive = name.startswith('i')
        return fnmatch.fnmatchcase(path.lower() if insensitive else path,
                                   arg.lower() if insensitive else arg)
    if name in ('hidden',):
        return os.path.basename(path).startswith('.') and os.path.basename(path) not in ('.', '..')
    if name == 'empty':
        if stat.S_ISDIR(st.st_mode):
            try:
                return next(os.scandir(path), None) is None
            except OSError:
                return False
        return st.st_size == 0
    if name in ('readable', 'writable', 'executable'):
        return os.access(path, {'readable': os.R_OK, 'writable': os.W_OK, 'executable': os.X_OK}[name])
    if name in ('amin', 'cmin', 'mmin', 'atime', 'ctime', 'mtime'):
        key = name[0]
        ts = {'a': st.st_atime, 'c': st.st_ctime, 'm': st.st_mtime}[key]
        units = 60 if name.endswith('min') else 86400
        age = int(((time.time() if now is None else now) - ts) / units)
        return _cmp(age, arg)
    if name == 'newer':
        try:
            return st.st_mtime > os.stat(arg).st_mtime
        except OSError:
            return False
    return None
